-- ==============================================================================
-- System Logs Maintenance Migration
-- ==============================================================================
--
-- Description:
-- Creates an automated, idempotent maintenance routine to safely prune internal
-- log tables generated by Supabase extensions (`pg_net` and `pg_cron`).
--
-- Safely Cleans:
--   1. `net._http_response`: HTTP logs from Edge Function triggers/webhooks.
--   2. `cron.job_run_details`: Execution logs for scheduled jobs.
--
-- Why it's Safe:
--   - Does NOT touch any application tables (`public.questions`, `public.synonym`, etc.).
--   - Only deletes data older than a configurable retention period.
--   - Uses batched deletion to prevent lock escalation and excessive WAL generation.
--   - Leaves enough recent data (7 days) so the admin dashboard RPCs
--     (`get_enrichment_dashboard_metrics` and `v2`) continue to function perfectly.
-- ==============================================================================

-- 1. Create a secure schema to hold maintenance constants (if it doesn't exist)
CREATE SCHEMA IF NOT EXISTS maintenance;

-- 2. Create the idempotent batched cleanup function
CREATE OR REPLACE FUNCTION maintenance.prune_system_logs(
    p_retention_http_days INT DEFAULT 7,
    p_retention_cron_days INT DEFAULT 7,
    p_batch_size INT DEFAULT 5000
)
RETURNS jsonb AS $$
DECLARE
    v_http_deleted INT := 0;
    v_cron_deleted INT := 0;
    v_batch_count INT := 0;
    v_start_time TIMESTAMPTZ := clock_timestamp();
    v_end_time TIMESTAMPTZ;
BEGIN
    -- --------------------------------------------------------------------------
    -- A. Prune `net._http_response` (HTTP Logs)
    -- Column: `created`
    -- --------------------------------------------------------------------------
    LOOP
        WITH deleted AS (
            DELETE FROM net._http_response
            WHERE id IN (
                SELECT id
                FROM net._http_response
                WHERE created < (NOW() - (p_retention_http_days || ' days')::INTERVAL)
                LIMIT p_batch_size
            )
            RETURNING 1
        )
        SELECT count(*) INTO v_batch_count FROM deleted;

        v_http_deleted := v_http_deleted + v_batch_count;

        -- Exit loop if we processed less than batch size (meaning we are done)
        EXIT WHEN v_batch_count < p_batch_size;
    END LOOP;

    -- --------------------------------------------------------------------------
    -- B. Prune `cron.job_run_details` (Cron Logs)
    -- Column: `start_time`
    -- --------------------------------------------------------------------------
    LOOP
        WITH deleted AS (
            DELETE FROM cron.job_run_details
            WHERE runid IN (
                SELECT runid
                FROM cron.job_run_details
                WHERE start_time < (NOW() - (p_retention_cron_days || ' days')::INTERVAL)
                LIMIT p_batch_size
            )
            RETURNING 1
        )
        SELECT count(*) INTO v_batch_count FROM deleted;

        v_cron_deleted := v_cron_deleted + v_batch_count;

        -- Exit loop if we processed less than batch size (meaning we are done)
        EXIT WHEN v_batch_count < p_batch_size;
    END LOOP;

    v_end_time := clock_timestamp();

    -- Return JSON summary for observability
    RETURN jsonb_build_object(
        'status', 'success',
        'http_rows_deleted', v_http_deleted,
        'cron_rows_deleted', v_cron_deleted,
        'execution_time_ms', EXTRACT(MILLISECONDS FROM (v_end_time - v_start_time)),
        'timestamp', NOW()
    );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- 3. Idempotent Cron Job Setup
-- Ensure `pg_cron` extension is active (should be in Supabase)
CREATE EXTENSION IF NOT EXISTS pg_cron;

DO $$
BEGIN
    -- Only unschedule if it exists
    IF EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'maintenance-prune-system-logs') THEN
        PERFORM cron.unschedule('maintenance-prune-system-logs');
    END IF;

    -- Schedule the cleanup to run daily at 03:00 AM UTC
    -- Uses default params (7 days retention, 5000 batch size)
    PERFORM cron.schedule(
        'maintenance-prune-system-logs',
        '0 3 * * *',
        'SELECT maintenance.prune_system_logs();'
    );
END $$;
